pub(crate) const AUTH_TABLE_SIZE: usize = 0x70 * 0x20;

const fn hex_nibble(value: u8) -> u8 {
    match value {
        b'0'..=b'9' => value - b'0',
        b'a'..=b'f' => value - b'a' + 10,
        _ => panic!("invalid internal hexadecimal table"),
    }
}

const fn decode_table(hex: &[u8]) -> [u8; AUTH_TABLE_SIZE] {
    assert!(
        hex.len() == AUTH_TABLE_SIZE * 2,
        "invalid authentication table length"
    );
    let mut table = [0_u8; AUTH_TABLE_SIZE];
    let mut index = 0;
    while index < table.len() {
        table[index] = (hex_nibble(hex[index * 2]) << 4) | hex_nibble(hex[index * 2 + 1]);
        index += 1;
    }
    table
}

pub(crate) const KEYS_A_PS4: [u8; AUTH_TABLE_SIZE] = decode_table(b"");
pub(crate) const KEYS_A_PS5: [u8; AUTH_TABLE_SIZE] = decode_table(b"");
pub(crate) const KEYS_B_PS4: [u8; AUTH_TABLE_SIZE] = decode_table(b"");
pub(crate) const KEYS_B_PS5: [u8; AUTH_TABLE_SIZE] = decode_table(b"");
